ReferenceQueue<Object> queue = new ReferenceQueue<>();
Object target = new Object();
WeakReference<Object> weakReference = new WeakReference<>(target, queue);

target = null; // usuwamy jedyna silna referencje
System.gc(); // tylko sugestia dla JVM

Reference<?> cleared = queue.poll(); // JVM sama wklada wyczyszczona referencje do kolejki

WeakReference<T> NIE zapobiega usunieciu obiektu przez GC - jesli jedyna referencja do obiektu to referencja slaba, GC MOZE go usunac przy NAJBLIZSZYM cyklu (nie czeka na presje pamieci, w odroznieniu od SoftReference). Klasyczne zastosowanie: WeakHashMap (klucze trzymane slabo - wpis znika automatycznie, gdy nikt inny nie trzyma klucza).

Cleaner cleaner = Cleaner.create();
Object resource = new Object();
// akcja sprzatajaca NIE MOZE trzymac referencji do 'resource'!
Cleaner.Cleanable cleanable = cleaner.register(resource, () -> {
    System.out.println("Akcja sprzatajaca wykonana - zasob zamkniety.");
});

PhantomReference<Object> phantomReference = new PhantomReference<>(resource, queue);
phantomReference.get(); // ZAWSZE zwraca null

resource = null;
System.gc();
cleanable.clean(); // idempotentne

PhantomReference jest NAJSLABSZYM typem referencji - get() zawsze zwraca null. Jej jedynym celem jest powiadomienie (przez ReferenceQueue), ze obiekt zostal juz uznany za martwy, wiec to bezpieczny moment na posprzatanie zasobow natywnych. Object.finalize() (przestarzale od Javy 9) mialo podobny cel, ale bylo nieprzewidywalne i moglo 'wskrzesic' obiekt - java.lang.ref.Cleaner (od Javy 9) to jej bezpieczny, nowoczesny zastepnik, zbudowany na PhantomReference.

String literalA = "javaquest";
String literalB = "javaquest";
String heapString = new String("javaquest");
String internedHeapString = heapString.intern();

literalA == literalB          // true - oba literaly, ta sama pula
literalA == heapString        // false - new String() OMIJA pule
literalA.equals(heapString)   // true - porownanie WARTOSCI
literalA == internedHeapString // true - po .intern(), z powrotem w puli

String pool to specjalny obszar pamieci (czesc sterty od Javy 7), gdzie JVM trzyma po jednej kopii kazdego literalu tekstowego. .intern() sprawdza, czy rownowazny String jest juz w puli - jesli tak, zwraca referencje do wersji z puli. Operator == porownuje REFERENCJE, .equals() porownuje WARTOSC - dla Stringow nalezy prawie zawsze uzywac .equals().

exercises.solution:
// WeakReference jest czyszczona przez GC przy NAJBLIZSZYM cyklu, gdy jedyna referencja do
// obiektu jest slaba - nie czeka na brak pamieci. SoftReference jest czyszczona DOPIERO
// pod PRESJA PAMIECI, tuz przed potencjalnym OutOfMemoryError - w praktyce trzyma dane
// 'jak najdluzej sie da'. PhantomReference jest NAJSLABSZA - get() ZAWSZE zwraca null,
// jej jedynym celem jest powiadomienie przez ReferenceQueue, ze obiekt zostal juz
// martwy/sfinalizowany, wiec mozna bezpiecznie posprzatac powiazane zasoby natywne.

Object obj = new Object();
WeakReference<Object> ref = new WeakReference<>(obj);
System.out.println("Przed: " + ref.get());
obj = null;
System.gc();
Thread.sleep(100);
System.out.println("Po: " + ref.get());

String literal = "kot";
String heap = new String("kot");
System.out.println("literal == heap: " + (literal == heap));
System.out.println("literal.equals(heap): " + literal.equals(heap));
// == daje false (rozne obiekty w pamieci), .equals() daje true (ta sama zawartosc znakow).

String heap = new String("pies");
String interned = heap.intern();
String literal = "pies";
System.out.println("interned == literal: " + (interned == literal));

SoftReference<byte[]> soft = new SoftReference<>(new byte[1024]);
System.out.println("get() != null: " + (soft.get() != null));
// GC wyczysciloby te referencje DOPIERO, gdyby stercie zabraklo miejsca (presja pamieci),
// tuz przed potencjalnym OutOfMemoryError - nie przy zwyklym, rutynowym cyklu GC.

Cleaner cleaner = Cleaner.create();
Object target = new Object();
cleaner.register(target, () -> System.out.println("Sprzatanie wykonane!"));
target = null;
System.gc();
Thread.sleep(200);

// PhantomReference.get() ZAWSZE zwraca null CELOWO - projekt tego mechanizmu zapobiega
// 'wskrzeszaniu' obiektu (ponownemu uzyskaniu do niego dostepu) w momencie, gdy JVM juz
// go uznala za martwy. Jedynym sposobem 'dowiedzenia sie' czegokolwiek jest ReferenceQueue -
// JVM sama wklada wyczyszczona referencje do przekazanej kolejki, wiec kod moze ja stamtad
// odebrac (queue.poll()/remove()) jako sygnal 'ten obiekt jest juz martwy, mozna sprzatac'.

// String pool to specjalny obszar pamieci (czesc sterty od Javy 7), gdzie JVM trzyma PO
// JEDNEJ kopii kazdego unikalnego literalu tekstowego. Gdy kompilator napotka literal
// String, sprawdza, czy identyczny juz istnieje w puli - jesli tak, UZYWA GO PONOWNIE
// zamiast tworzyc nowy obiekt. Dlatego "Ala" napisane w 5 roznych miejscach kodu to w
// rzeczywistosci JEDEN obiekt String w pamieci, oszczedzajacy pamiec dla czestych,
// powtarzajacych sie tekstow (np. nazw pol, stalych).

// Object.finalize() jest przestarzale od Javy 9 z kilku powodow: (1) czas jego wywolania
// jest calkowicie NIEPRZEWIDYWALNY (moze nie wywolac sie WCALE przed zakonczeniem JVM),
// (2) obiekt MOZE zostac 'wskrzeszony' wewnatrz finalize() przez przypisanie referencji do
// niego z zewnatrz, co komplikuje logike GC, (3) wyjatek rzucony w finalize() jest cicho
// ignorowany. Cleaner jest lepszy, bo: (1) dziala na PhantomReference, wiec NIE MOZE
// wskrzesic obiektu (get() zawsze null), (2) akcja sprzatajaca jest zwyklym Runnable,
// latwiejszym do przetestowania i zrozumienia niz przeciazona metoda instancji.

String compileTime = "java" + "quest";
String literal = "javaquest";
System.out.println("compileTime == literal: " + (compileTime == literal));
// true - kompilator LACZY stale literaly w czasie kompilacji (constant folding), wiec
// wynikowy String trafia do puli DOKLADNIE tak samo, jakby byl napisany jako pojedynczy
// literal "javaquest".

ReferenceQueue<Object> queue = new ReferenceQueue<>();
Object o = new Object();
WeakReference<Object> ref = new WeakReference<>(o, queue);
o = null;
System.gc();
Reference<?> cleared = null;
for (int i = 0; i < 20 && cleared == null; i++) {
    cleared = queue.poll();
    if (cleared == null) Thread.sleep(50);
}
System.out.println("Pojawila sie w kolejce: " + (cleared != null));

String part = "java";
String result = part + "quest";
String literal = "javaquest";
System.out.println("result == literal: " + (result == literal));
// false - konkatenacja Z UDZIALEM zmiennej dzieje sie w RUNTIME (kompilator uzywa
// StringBuildera pod spodem), wiec wynikowy obiekt jest NOWY, na stercie, POZA pula -
// w odroznieniu od Zadania 10, gdzie oba skladniki byly stalymi znanymi juz w compile-time.

Map<String, WeakReference<byte[]>> cache = new HashMap<>();
cache.put("a", new WeakReference<>(new byte[1024]));
cache.put("b", new WeakReference<>(new byte[1024]));
cache.put("c", new WeakReference<>(new byte[1024]));
System.gc();
Thread.sleep(200);
cache.forEach((k, v) -> System.out.println(k + ": " + (v.get() == null ? "wyczyszczone" : "nadal zywe")));

// Jesli aplikacja wywoluje .intern() na MILIONACH roznych, dynamicznie generowanych
// Stringow (np. losowych identyfikatorow sesji, tresci z requestow uzytkownikow), kazdy
// z nich trafia do String pool i tam POZOSTAJE. String pool tez zajmuje pamiec sterty -
// jesli wiekszosc tych Stringow jest UNIKALNA (nigdy sie nie powtarza), .intern() NIE
// przynosi zadnej oszczednosci (bo nic sie nie wspoldzieli), a jedynie POWIEKSZA pule o
// coraz to nowe wpisy, ktore w normalnym przypadku (bez intern) zostalyby po prostu
// zebrane przez zwykly GC jak kazdy inny obiekt.

static class ManagedResource {
    private static final Cleaner CLEANER = Cleaner.create();
    ManagedResource(String name) {
        CLEANER.register(this, new CleanupAction(name));
    }
    static class CleanupAction implements Runnable {
        private final String name;
        CleanupAction(String name) { this.name = name; }
        public void run() { System.out.println("Zasob " + name + " zamkniety"); }
    }
}

ManagedResource r = new ManagedResource("X");
r = null;
System.gc();
Thread.sleep(200);

ReferenceQueue<Object> queue = new ReferenceQueue<>();
Object o = new Object();
WeakReference<Object> ref = new WeakReference<>(o, queue);
o = null;
long start = System.nanoTime();
System.gc();
Reference<?> cleared = null;
for (int i = 0; i < 20 && cleared == null; i++) {
    cleared = queue.poll();
    if (cleared == null) Thread.sleep(50);
}
long elapsedMs = (System.nanoTime() - start) / 1_000_000;
System.out.println("Czas: " + elapsedMs + " ms, znaleziono: " + (cleared != null));

String[] interned = new String[5];
for (int i = 0; i < 5; i++) {
    interned[i] = new String("duplikat").intern();
}
boolean wszystkieTakieSame = true;
for (int i = 1; i < 5; i++) {
    if (interned[i] != interned[0]) wszystkieTakieSame = false;
}
System.out.println("Wszystkie zinternowane wersje to ten sam obiekt: " + wszystkieTakieSame);

// Realny scenariusz: framework GUI (np. mapujacy dodatkowe metadane do komponentow ekranu)
// chce trzymac 'dodatkowe dane' powiazane z obiektem komponentu, ale NIE chce byc
// odpowiedzialny za jawne usuwanie wpisu, gdy komponent zostanie zniszczony/usuniety z
// ekranu przez reszte aplikacji. Zwykla HashMap<Komponent, Dane> trzymalaby SILNA
// referencje do komponentu jako klucza - nawet, gdy caly ekran zostal juz zamkniety i
// nikt inny nie trzyma do niego referencji, wpis w HashMap zapobiegalby jego usunieciu
// przez GC (klasyczny wyciek pamieci). WeakHashMap<Komponent, Dane> trzyma klucz SLABO -
// gdy komponent stanie sie nieosiagalny NIGDZIE indziej w aplikacji, GC moze go usunac, a
// wpis w WeakHashMap zniknie AUTOMATYCZNIE, bez potrzeby recznego sprzatania przez framework.

ReferenceQueue<Object> queue = new ReferenceQueue<>();
Object a = new Object(), b = new Object(), c = new Object();
PhantomReference<Object> pa = new PhantomReference<>(a, queue);
PhantomReference<Object> pb = new PhantomReference<>(b, queue);
PhantomReference<Object> pc = new PhantomReference<>(c, queue);
a = null; b = null; c = null;
System.gc();
int count = 0;
for (int i = 0; i < 20 && count < 3; i++) {
    while (queue.poll() != null) count++;
    if (count < 3) Thread.sleep(50);
}
System.out.println("Wyczyszczone: " + count + "/3");

// Od Javy 9 (Compact Strings, JEP 254) String uzywa 1 bajta na znak, jesli WSZYSTKIE
// znaki miesza sie w kodowaniu Latin-1 - "ala ma kota" sklada sie wylacznie z liter
// podstawowego alfabetu lacinskiego i spacji, wiec kwalifikuje sie do trybu 1 bajt/znak.
// Emoji NIE miesci sie w Latin-1 (wymaga pelnego zakresu Unicode) - gdy String zawiera
// CHOCBY JEDEN taki znak, JVM przelacza CALY String (nie tylko ten jeden znak) na pelne
// kodowanie UTF-16, czyli 2 bajty na KAZDY znak tego Stringa, nawet te 'proste' litery.

static class SimpleWeakCache<K, V> {
    private final Map<K, WeakReference<V>> map = new HashMap<>();
    void put(K key, V value) { map.put(key, new WeakReference<>(value)); }
    V get(K key) {
        WeakReference<V> ref = map.get(key);
        return ref == null ? null : ref.get();
    }
    void cleanupCleared() {
        map.entrySet().removeIf(e -> e.getValue().get() == null);
    }
}

List<String> normal = new ArrayList<>();
List<String> interned = new ArrayList<>();
for (int i = 0; i < 1000; i++) {
    String s = "prefix-" + i;
    normal.add(s);
    interned.add(s.intern());
}
int matchesInterned = 0, matchesNormal = 0;
for (int i = 0; i < 500; i++) {
    if (interned.get(i) == ("prefix-" + i).intern()) matchesInterned++;
    if (normal.get(i) == ("prefix-" + i)) matchesNormal++;
}
System.out.println("Dopasowania interned: " + matchesInterned + ", zwykle: " + matchesNormal);

static class ResourceTracker {
    private final ReferenceQueue<Object> queue = new ReferenceQueue<>();
    private final List<PhantomReference<Object>> refs = new ArrayList<>();
    void register(Object resource) { refs.add(new PhantomReference<>(resource, queue)); }
    int drainClearedCount() {
        int count = 0;
        while (queue.poll() != null) count++;
        return count;
    }
}

ResourceTracker tracker = new ResourceTracker();
Object a = new Object(), b = new Object(), c = new Object(), d = new Object(), e = new Object();
tracker.register(a); tracker.register(b); tracker.register(c); tracker.register(d); tracker.register(e);
a = null; b = null; c = null;
System.gc();
Thread.sleep(200);
System.out.println("Wyczyszczone: " + tracker.drainClearedCount());

Object strong = new Object();
WeakReference<Object> weak = new WeakReference<>(new Object());
SoftReference<Object> soft = new SoftReference<>(new Object());
PhantomReference<Object> phantom = new PhantomReference<>(new Object(), new ReferenceQueue<>());
System.out.printf("%-10s | %s%n", "Strong", strong != null);
System.out.printf("%-10s | %s%n", "Weak", weak.get() != null);
System.out.printf("%-10s | %s%n", "Soft", soft.get() != null);
System.out.printf("%-10s | %s%n", "Phantom", phantom.get() != null);

static class NativeHandle {
    private static final Cleaner CLEANER = Cleaner.create();
    private final Cleaner.Cleanable cleanable;
    NativeHandle(int fd) {
        this.cleanable = CLEANER.register(this, new HandleCleanup(fd));
    }
    void close() { cleanable.clean(); }
    static class HandleCleanup implements Runnable {
        private final int fd;
        HandleCleanup(int fd) { this.fd = fd; }
        public void run() { System.out.println("Uchwyt " + fd + " zwolniony"); }
    }
}

NativeHandle h1 = new NativeHandle(1);
NativeHandle h2 = new NativeHandle(2);
NativeHandle h3 = new NativeHandle(3);
h1.close(); // jawne zwolnienie
h2 = null; h3 = null;
System.gc();
Thread.sleep(200);

// GC usuwa TYLKO obiekty, do ktorych NIE MA zadnej silnej referencji z 'GC root' - jesli
// program SAM trzyma silna referencje do obiektu, ktorego juz logicznie nie potrzebuje,
// GC nie moze mu pomoc, bo z jego perspektywy obiekt jest wciaz 'zywy' i uzywany.
// Klasyczny przyklad: statyczna kolekcja (np. `static List<Sesja> aktywneSesje`), do
// ktorej program DODAJE elementy, ale nigdy z niej nie USUWA po zakonczeniu sesji -
// kolekcja rosnie bez ograniczen przez caly czas dzialania aplikacji, zuzywajac coraz
// wiecej pamieci, mimo ze wiekszosc sesji dawno sie zakonczyla. Podobnie dzieje sie z
// niezarejestrowanymi listenerami zdarzen - jesli obiekt A rejestruje sie jako listener w
// dlugozyjacym obiekcie B i NIGDY sie nie wyrejestrowuje, B trzyma A przy zyciu na zawsze,
// nawet gdy reszta aplikacji juz o A zapomniala. WeakReference pomaga, bo pozwala
// dlugozyjacemu obiektowi (kolekcji/listenerowi) trzymac referencje SLABO - gdy zaden
// INNY kod juz nie potrzebuje danego obiektu, GC moze go usunac mimo, ze wciaz jest
// wpisany w te 'dlugozyjaca' strukture (patrz WeakHashMap z Zadania 18).

long buildStart = System.nanoTime();
List<String> list = new ArrayList<>();
for (int i = 0; i < 100_000; i++) list.add("unikalny-" + i);
long buildMs = (System.nanoTime() - buildStart) / 1_000_000;

long internStart = System.nanoTime();
for (String s : list) s.intern();
long internMs = (System.nanoTime() - internStart) / 1_000_000;

System.out.println("Budowa: " + buildMs + " ms, intern: " + internMs + " ms");
// Kompromis: .intern() kosztuje dodatkowy CZAS CPU (przeszukanie/wpis do puli) na kazdy
// String, a przy WSZYSTKICH unikalnych wartosciach NIE przynosi zadnej oszczednosci pamieci -
// jedynie powieksza pule o te same 100 000 wpisow, ktore i tak zostalyby zebrane przez GC.

// Dla cache wynikow drogich obliczen (np. wynikow zapytan do bazy, przetworzonych
// obrazow) LEPSZYM wyborem jest SoftReference, nie WeakReference. WeakReference
// zostalaby wyczyszczona przy KAZDYM, nawet rutynowym cyklu GC (mlodej generacji), co w
// praktyce oznaczaloby, ze cache jest niemal bezuzyteczny - dane znikalyby niemal
// natychmiast po utworzeniu, zanim ktokolwiek zdazyl je ponownie wykorzystac.
// SoftReference trzyma dane 'tak dlugo jak to mozliwe' i jest czyszczona DOPIERO pod
// realna presja pamieci (blisko OutOfMemoryError) - co oznacza, ze cache dziala
// efektywnie w normalnych warunkach, a automatycznie 'oddaje' pamiec DOKLADNIE wtedy,
// gdy jest ona naprawde potrzebna gdzie indziej, zamiast doprowadzic do awarii aplikacji.

ReferenceQueue<Object> queue = new ReferenceQueue<>();
Map<Reference<?>, Integer> idMap = new HashMap<>();
Object[] resources = new Object[10];
for (int i = 0; i < 10; i++) {
    resources[i] = new Object();
    PhantomReference<Object> ref = new PhantomReference<>(resources[i], queue);
    idMap.put(ref, i);
}
for (int i = 0; i < 10; i++) resources[i] = null;
System.gc();
int processed = 0;
for (int attempt = 0; attempt < 40 && processed < 10; attempt++) {
    Reference<?> ref = queue.poll();
    if (ref != null) {
        System.out.println("Zasob " + idMap.get(ref) + " wyczyszczony");
        processed++;
    } else {
        Thread.sleep(50);
    }
}
System.out.println("Przetworzono: " + processed + "/10");

System.out.println("=== RAPORT: TYPY REFERENCJI I STRING POOL ===");

System.out.println("--- WeakReference ---");
ReferenceQueue<Object> wq = new ReferenceQueue<>();
Object wobj = new Object();
WeakReference<Object> wref = new WeakReference<>(wobj, wq);
wobj = null;
System.gc();
boolean cleared = false;
for (int i = 0; i < 20 && !cleared; i++) {
    if (wq.poll() != null) cleared = true; else Thread.sleep(50);
}
System.out.println("Wyczyszczona: " + cleared);

System.out.println("--- PhantomReference + Cleaner ---");
Cleaner cleaner = Cleaner.create();
Object presource = new Object();
cleaner.register(presource, () -> System.out.println("Zasob posprzatany przez Cleaner!"));
presource = null;
System.gc();
Thread.sleep(200);

System.out.println("--- String pool ---");
String a = "raport";
String b = "raport";
String c = new String("raport");
System.out.println("a == b: " + (a == b));
System.out.println("a == c: " + (a == c));
System.out.println("a.equals(c): " + a.equals(c));
System.out.println("a == c.intern(): " + (a == c.intern()));
